import React, { useState, useEffect } from "react";
import { MapContainer, TileLayer, GeoJSON } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import Slider from "react-slider";
import "./App.css";

function App() {
  const [year, setYear] = useState(2012);
  const [geoData, setGeoData] = useState(null);

  // Загрузка GeoJSON при изменении года
  useEffect(() => {
    fetch(`/data/elections-${year}.geojson`)
      .then((res) => res.json())
      .then((data) => setGeoData(data))
      .catch((err) => console.error("Ошибка загрузки GeoJSON:", err));
  }, [year]);

  return (
    <div className="App">
      <h1>Геопортал: Выборы в Москве</h1>

      {/* Кнопки выбора типа выборов */}
      <div className="controls">
        <button>Госдума</button>
        <button>Мосгордума</button>
        <button>Муниципальные</button>
        <button>Мэр</button>
        <button>Президент</button>
      </div>

      {/* Карта */}
      <MapContainer
        center={[55.7558, 37.6173]}
        zoom={10}
        style={{ height: "500px", width: "100%", borderRadius: "8px" }}
      >
        <TileLayer
          attribution='&copy; <a href="http://osm.org/copyright">OpenStreetMap</a>'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        {geoData && (
          <GeoJSON
            data={geoData}
            style={() => ({
              color: "#007bff",
              weight: 1,
              fillOpacity: 0.25,
            })}
            onEachFeature={(feature, layer) => {
              const props = feature.properties;
              const label = props?.name || props?.id || "Участок";
              layer.bindPopup(`<b>${label}</b>`);
            }}
          />
        )}
      </MapContainer>

      {/* Слайдер по годам */}
      <div className="slider-container">
        <label>Год: {year}</label>
        <Slider
          className="slider"
          value={year}
          min={2012}
          max={2022}
          step={1}
          onChange={setYear}
          renderTrack={(props) => <div {...props} className="slider-track" />}
          renderThumb={(props) => <div {...props} className="slider-thumb" />}
        />
      </div>
    </div>
  );
}

export default App;
